"""Extract known TIDizzy sprites or tutorial-room graphics without overwrites."""

import argparse
import hashlib
import json
from itertools import groupby
from pathlib import Path
import struct

from PIL import Image

import sys
sys.path.insert(0, str(Path(__file__).resolve().parent))
from asm_header import asm_header  # noqa: E402

ROOT = Path(__file__).resolve().parent.parent
DISK = ROOT / "assembly" / "blog5" / "TIDizzy.dsk"
OUT = ROOT / "assembly" / "blog5" / "tidizzy"

FILE_NAME = "AUTOmain.O"
FILE_LENGTH = 447262  # from the directory entry
PALETTE_OFFSET = 28066  # offset into the file; palette bytes are the 16 CLUT values
FIRST_IMAGE = 180421  # offset of Image1's width byte
IMAGE_COUNT = 62
DISK_SHA256 = "76d31404b5f11605c0054aaf519f536dc3d7c78dbfffbf8a9bdaefc082a72512"
DISK_SIZE = 80 * 2 * 10 * 512
ROOM_TABLE = 0x3C000
GRAPHICS_TABLE = 0xC000
TUTORIAL_ROOMS = (77, 76, 108, 107)
ROOM_ASSEMBLY_HEADERS = {
    "room-graphics.asm": ("Room Graphics", "Generated graphics-only bank data; see provenance.json."),
    "room-data.asm": ("Room Draw Records", "Generated seven-byte draw records; signed clipping is resolved offline."),
    "room-collision.asm": ("Room Collision", "Generated collision runs: word count, byte value; zero word terminates."),
}


SPRITE_ASSEMBLY_HEADER = asm_header(
    "SAM Coupe Sprites Tutorials - All Extracted Sprites", "tidizzy_all.asm",
    description=["Generated by .vscode\\extract_tidizzy.py from the game disk.",
                 "Each ImageN starts with its width in screen bytes and its height in rows."],
)


def room_assembly_header(name):
    title, description = ROOM_ASSEMBLY_HEADERS[name]
    return asm_header(f"SAM Coupe Sprites Tutorials - {title}", name, description=[description])


def sector(disk, track, sec):
    if not (0 <= track <= 207 and (track & 127) < 80 and 1 <= sec <= 10):
        raise ValueError(f"Invalid sector address: track {track}, sector {sec}")
    side = 1 if track >= 128 else 0
    offset = (((track & 127) * 2 + side) * 10 + (sec - 1)) * 512
    block = disk[offset : offset + 512]
    if len(block) != 512:
        raise ValueError(f"Truncated sector: track {track}, sector {sec}")
    return block


def read_file(disk, wanted):
    if len(disk) != DISK_SIZE:
        raise ValueError(f"Expected an {DISK_SIZE}-byte raw MGT disk image")
    for entry_no in range(80):
        entry = sector(disk, entry_no // 20, 1 + (entry_no % 20) // 2)[
            (entry_no % 2) * 256 :
        ][:256]
        if entry[0] and entry[1:11].decode("latin1").strip() == wanted:
            track, sec = entry[13], entry[14]
            data = bytearray()
            visited = set()
            while (track, sec) != (0, 0):
                if track < 4:
                    raise ValueError("File chain points into directory tracks")
                if (track, sec) in visited:
                    raise ValueError("Cycle in disk file sector chain")
                visited.add((track, sec))
                block = sector(disk, track, sec)
                data.extend(block[:510])
                track, sec = block[510], block[511]
            if len(data) < 9:
                raise ValueError(f"{wanted} has no complete file header")
            return data[9:]  # drop the 9 byte file header
    raise ValueError(f"{wanted} not found on the disk")


def known_payload(disk):
    if hashlib.sha256(disk).hexdigest() != DISK_SHA256:
        raise ValueError("Unsupported disk: SHA-256 does not match the known TIDizzy release")
    payload = read_file(disk, FILE_NAME)
    if len(payload) < FILE_LENGTH:
        raise ValueError(f"{FILE_NAME} is shorter than its expected {FILE_LENGTH} bytes")
    return payload[:FILE_LENGTH]


def extract_sprites(disk):
    code = known_payload(disk)
    palette = list(code[PALETTE_OFFSET : PALETTE_OFFSET + 16])
    if len(palette) != 16 or any(value > 127 for value in palette):
        raise ValueError("Expected 16 SAM CLUT values")
    images = []
    offset = FIRST_IMAGE
    for number in range(1, IMAGE_COUNT + 1):
        if offset + 2 > len(code):
            raise ValueError(f"Missing sprite {number} header")
        width, height = code[offset : offset + 2]
        end = offset + 2 + width * height
        if not (1 <= width <= 20 and 1 <= height <= 32) or end > len(code):
            raise ValueError(f"Invalid or truncated sprite {number} at offset {offset}")
        rows = [code[offset + 2 + r * width : offset + 2 + (r + 1) * width] for r in range(height)]
        images.append((width, height, rows))
        offset = end
    return palette, images, offset


def clut_rgb(value):
    bright = (value >> 3) & 1

    def level(high, low):
        return int((((value >> high) & 1) * 4 + ((value >> low) & 1) * 2 + bright) / 7 * 255)

    return level(5, 1), level(6, 2), level(4, 0)


def read_graphic(code, image):
    if not 0 <= image or GRAPHICS_TABLE + image * 3 + 3 > FIRST_IMAGE:
        raise ValueError(f"Invalid image identifier {image}")
    page, address = struct.unpack_from("<BH", code, GRAPHICS_TABLE + image * 3)
    position = (3 + page) * 0x4000 + address
    if page > 11 or address >= 0x8000 or position + 2 > len(code):
        raise ValueError(f"Invalid graphics pointer for image {image}")
    width, height = code[position : position + 2]
    last = position + 2 + width * height
    if not (1 <= width <= 128 and 1 <= height <= 192 and last <= ROOM_TABLE):
        raise ValueError(f"Invalid graphics dimensions for image {image}")
    return {
        "offset": position,
        "width_bytes": width,
        "height": height,
        "pixels": bytes(code[position + 2 : last]),
    }


def export_graphics(disk_path, output, identifiers):
    code = known_payload(disk_path.read_bytes())
    graphics = {number: read_graphic(code, number) for number in identifiers}
    output.mkdir(parents=True, exist_ok=False)
    for number, graphic in graphics.items():
        (output / f"image-{number}.bin").write_bytes(
            bytes((graphic["width_bytes"], graphic["height"])) + graphic["pixels"]
        )
    provenance = {
        "source_sha256": DISK_SHA256,
        "graphics_table_offset": GRAPHICS_TABLE,
        "graphics": {
            str(number): {key: value for key, value in graphic.items() if key != "pixels"}
            for number, graphic in graphics.items()
        },
        "scope": "Selected graphics only; no original game code.",
    }
    (output / "provenance.json").write_text(json.dumps(provenance, indent=2) + "\n", encoding="ascii")
    print(f"Wrote {len(graphics)} selected graphics to {output}")


def extract_rooms(disk):
    code = known_payload(disk)
    palette = list(code[PALETTE_OFFSET : PALETTE_OFFSET + 16])
    if len(palette) != 16 or any(value > 127 for value in palette):
        raise ValueError("Expected 16 SAM CLUT values")
    rooms, graphics = [], {}
    for screen, number in enumerate(TUTORIAL_ROOMS, 1):
        pointer, following = struct.unpack_from("<HH", code, ROOM_TABLE + number * 2)
        offset = ROOM_TABLE + pointer
        end = ROOM_TABLE + following
        if not (ROOM_TABLE + 512 <= offset < end <= ROOM_TABLE + 0x8000):
            raise ValueError(f"Invalid room {number} list boundaries")
        count = code[offset]
        if offset + 1 + count * 6 != end:
            raise ValueError(f"Invalid room {number} draw-list length")
        entries = []
        for i in range(count):
            low, flags, x, y = struct.unpack_from("<BBhh", code, offset + 1 + i * 6)
            image = low + ((flags & 127) << 8)
            if image not in graphics:
                graphics[image] = read_graphic(code, image)
            entries.append({
                "image": image,
                "collision": bool(flags & 128),
                "x_bytes": x,
                "y": y,
                "water": image == 55,
            })
        rooms.append({
            "screen": screen,
            "native_room": number,
            "list_offset": offset,
            "entries": entries,
        })
    return palette, rooms, graphics


def render_room(entries, graphics):
    pixels, collision = bytearray(0x6000), bytearray(0x6000)
    for water_pass in (False, True):
        for entry in entries:
            if entry["water"] != water_pass:
                continue
            graphic = graphics[entry["image"]]
            width, height = graphic["width_bytes"], graphic["height"]
            for row in range(height):
                y = entry["y"] + row
                if not 48 <= y < 192:
                    continue
                for column in range(width):
                    x = entry["x_bytes"] + column
                    if not 0 <= x < 128:
                        continue
                    value = graphic["pixels"][row * width + column]
                    mask = (0xF0 if value & 0xF0 else 0) | (0x0F if value & 0x0F else 0)
                    address = y * 128 + x
                    pixels[address] = (pixels[address] & (mask ^ 255)) | value
                    if entry["collision"]:
                        collision[address] |= mask
    return bytes(pixels), bytes(collision)


def clipped_draws(entries, graphics):
    draws = []
    for water_pass in (False, True):
        for entry in entries:
            if entry["water"] != water_pass:
                continue
            graphic = graphics[entry["image"]]
            stride, rows = graphic["width_bytes"], graphic["height"]
            x, y = entry["x_bytes"], entry["y"]
            left, top = max(x, 0), max(y, 48)
            right, bottom = min(x + stride, 128), min(y + rows, 192)
            if left < right and top < bottom:
                draws.append({
                    "image": entry["image"],
                    "source_skip": 2 + (top - y) * stride + left - x,
                    "destination": top * 128 + left,
                    "width": right - left,
                    "height": bottom - top,
                    "stride": stride,
                })
    return draws


def collision_runs(collision):
    if len(collision) != 0x6000 or any(value not in (0, 15, 240, 255) for value in collision):
        raise ValueError("Collision map must contain 24 KB of empty/solid nibbles")
    return [(sum(1 for _ in run), value) for value, run in groupby(collision)]


def export_room_assembly(output, rooms, graphics):
    graphics_lines = room_assembly_header("room-graphics.asm")
    for number in sorted(graphics):
        graphics_lines += [
            f"Room_Image_{number}: ; Source graphic {number}, including its dimensions header",
            f'                MDAT "graphics\\image-{number}.bin" ; Packed source-game pixels',
        ]
    room_lines = room_assembly_header("room-data.asm")
    for room in rooms:
        draws = clipped_draws(room["entries"], graphics)
        room_lines.append(f"Room_{room['screen']}: DEFB {len(draws)} ; Number of visible graphic blocks")
        for draw in draws:
            room_lines += [
                f"                DEFW Room_Image_{draw['image']}+{draw['source_skip']} "
                "; Source bytes after header and clipping",
                f"                DEFW {draw['destination']} ; Packed destination screen offset",
                f"                DEFB {draw['width']},{draw['height']},{draw['stride']} "
                "; Visible width, height and original source stride",
            ]
    collision_lines = room_assembly_header("room-collision.asm")
    for room in rooms:
        _, collision = render_room(room["entries"], graphics)
        collision_lines.append(f"Room_{room['screen']}_Collision: ; Separate source-derived solidity")
        for count, value in collision_runs(collision):
            collision_lines += [
                f"                DEFW {count} ; Consecutive bytes with identical solidity",
                f"                DEFB {value} ; Packed high/low solidity nibbles",
            ]
        collision_lines.append("                DEFW 0 ; End of this complete 24 KB collision map")
    for name, lines in (
        ("room-graphics.asm", graphics_lines),
        ("room-data.asm", room_lines),
        ("room-collision.asm", collision_lines),
    ):
        with (output / name).open("x", encoding="ascii", newline="\n") as destination:
            destination.write("\n".join(lines) + "\n")


def export_rooms(disk_path, output):
    palette, rooms, graphics = extract_rooms(disk_path.read_bytes())
    output.mkdir(parents=True, exist_ok=False)
    asset_folder = output / "graphics"
    asset_folder.mkdir()
    for number, graphic in sorted(graphics.items()):
        (asset_folder / f"image-{number}.bin").write_bytes(
            bytes((graphic["width_bytes"], graphic["height"])) + graphic["pixels"]
        )
    export_room_assembly(output, rooms, graphics)
    rgb_palette = [component for value in palette for component in clut_rgb(value)]
    for room in rooms:
        pixels, collision = render_room(room["entries"], graphics)
        stem = f"screen-{room['screen']}"
        (output / f"{stem}.bin").write_bytes(pixels)
        (output / f"{stem}-collision.bin").write_bytes(collision)
        image = Image.new("P", (256, 192))
        image.putpalette(rgb_palette + [0] * (768 - len(rgb_palette)))
        image.putdata([colour for value in pixels for colour in (value >> 4, value & 15)])
        image.save(output / f"{stem}.png")
    provenance = {
        "source_sha256": DISK_SHA256,
        "file_name": FILE_NAME,
        "palette_offset": PALETTE_OFFSET,
        "palette": palette,
        "room_table_offset": ROOM_TABLE,
        "graphics_table_offset": GRAPHICS_TABLE,
        "rooms": rooms,
        "graphics": {
            str(number): {key: value for key, value in graphic.items() if key != "pixels"}
            for number, graphic in sorted(graphics.items())
        },
        "scope": "Four-room scenery and static collision only; no original game code.",
        "rendering": "MODE 4; 128-byte stride; rows 48-191; colour-zero transparency; "
                     "water uses its first animation frame. HUD, player, items and actors excluded.",
        "collision": "Each nonzero source nibble in a collision-flagged draw entry sets "
                     "that nibble to 15. Dynamic support and hazards are separate.",
    }
    (output / "provenance.json").write_text(json.dumps(provenance, indent=2) + "\n", encoding="ascii")
    print(f"Wrote {len(rooms)} rooms and {len(graphics)} graphics to {output}")


def export_sprites(disk_path, output):
    palette, images, end = extract_sprites(disk_path.read_bytes())
    output.mkdir(parents=True, exist_ok=False)
    lines = SPRITE_ASSEMBLY_HEADER + ["Palette:", "\t\tdb\t" + ", ".join(f"&{v:02X}" for v in palette), ""]
    for number, (width, height, rows) in enumerate(images, 1):
        lines += [f"Image{number}:", f"\t\tdb\t{width}, {height}"]
        lines += ["\t\tdb\t" + ", ".join(f"&{v:02X}" for v in row) for row in rows]
    (output / "tidizzy_all.asm").write_text("\n".join(lines) + "\n", encoding="ascii", newline="\n")

    colours = [clut_rgb(v) for v in palette]
    scale, per_row = 3, 8
    cell_w = max(width * 2 for width, _, _ in images) * scale + 4
    cell_h = max(height for _, height, _ in images) * scale + 4
    sheet = Image.new(
        "RGB", (per_row * cell_w, ((len(images) + per_row - 1) // per_row) * cell_h), (40, 40, 40)
    )
    for number, (width, height, rows) in enumerate(images):
        ox, oy = (number % per_row) * cell_w + 2, (number // per_row) * cell_h + 2
        for y, row in enumerate(rows):
            for x, value in enumerate(row):
                for half, colour in enumerate((value >> 4, value & 15)):
                    if colour:
                        for dx in range(scale):
                            for dy in range(scale):
                                sheet.putpixel(
                                    (ox + (x * 2 + half) * scale + dx, oy + y * scale + dy),
                                    colours[colour],
                                )
    sheet.save(output / "tidizzy_sheet.png")
    provenance = {
        "source_sha256": DISK_SHA256,
        "file_name": FILE_NAME,
        "file_length": FILE_LENGTH,
        "palette_offset": PALETTE_OFFSET,
        "palette": palette,
        "first_image_offset": FIRST_IMAGE,
        "images_end_offset": end,
        "image_count": len(images),
        "dimensions_bytes_rows": [[width, height] for width, height, _ in images],
        "scope": "Sprite graphics only; no original game code or full disk.",
    }
    (output / "provenance.json").write_text(
        json.dumps(provenance, indent=2) + "\n", encoding="ascii"
    )
    print(f"Wrote {len(images)} images to {output}")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--disk", type=Path, default=DISK, help="Known raw MGT disk image")
    parser.add_argument("--output", type=Path, default=OUT, help="New output directory (must not exist)")
    modes = parser.add_mutually_exclusive_group()
    modes.add_argument("--rooms", action="store_true", help="Extract the four tutorial rooms, not sprites")
    modes.add_argument("--graphics", nargs="+", type=int, help="Extract selected graphics-table identifiers")
    args = parser.parse_args()
    try:
        if args.graphics is not None:
            export_graphics(args.disk, args.output, args.graphics)
        else:
            exporter = export_rooms if args.rooms else export_sprites
            exporter(args.disk, args.output)
    except (OSError, ValueError) as error:
        parser.exit(1, f"Graphics extraction failed: {error}\n")


if __name__ == "__main__":
    main()
